                            to_remove.add(ridx)
        routes = [r for r in routes if r]

        # Reinsert missing by best feasible insertion
        for c in missing:
            best_r = None
            best_pos = None
            best_cost = None
            for ridx, r in enumerate(routes):
                load = 0
                for x in r:
                    load += demand[x]
                if load + demand[c] > cap:
                    continue
                # best insertion position minimizing detour
                for p in range(len(r) + 1):
                    prev = depot if p == 0 else r[p - 1]
                    nxt = depot if p == len(r) else r[p]
                    cost = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    key = (cost, ridx, p)
                    if best_cost is None or key < best_cost:
                        best_cost = key
                        best_r = ridx
                        best_pos = p
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_pos, c)

    # ---------- local search: intra-route 2-opt ----------
    def route_cost(r):
        if not r:
            return 0.0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        s += dist(r[-1], depot)
        return s

    improved = True
    while improved:
        improved = False
        for r in routes:
            n = len(r)
            if n < 4:
                continue
            best_gain = 0.0
            best_i = best_j = None
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j]
                    d = depot if j == n - 1 else r[j + 1]
                    old = dist(a, b) + dist(c, d)
                    new = dist(a, c) + dist(b, d)
                    gain = old - new
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_gain > 1e-12:
                r[best_i:best_j + 1] = reversed(r[best_i:best_j + 1])
                improved = True

    # ---------- local search: relocate between routes ----------
    def load_of(r):
        s = 0
        for x in r:
            s += demand[x]
        return s

    improved = True
    while improved:
        improved = False
        loads = [load_of(r) for r in routes]
        best_move = None
        best_gain = 0.0
        for i, r1 in enumerate(routes):
            for p, c in enumerate(r1):
                for j, r2 in enumerate(routes):
                    if i == j:
                        continue
                    if loads[j] + demand[c] > cap:
                        continue
                    # remove from r1
                    prev1 = depot if p == 0 else r1[p - 1]
                    next1 = depot if p == len(r1) - 1 else r1[p + 1]
                    remove_gain = dist(prev1, c) + dist(c, next1) - dist(prev1, next1)
                    # insert into r2 best position
                    best_ins = None
                    best_ins_cost = None
                    for q in range(len(r2) + 1):
                        prev2 = depot if q == 0 else r2[q - 1]
                        next2 = depot if q == len(r2) else r2[q]
                        ins = dist(prev2, c) + dist(c, next2) - dist(prev2, next2)
                        if best_ins_cost is None or ins < best_ins_cost:
                            best_ins_cost = ins
                            best_ins = q
                    gain = remove_gain - best_ins_cost
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_move = (i, p, j, best_ins)
        if best_move is not None:
            i, p, j, q = best_move
            c = routes[i].pop(p)
            if i < j and len(routes[i]) == 0:
                # route indices shift after pop
                routes[j - 1].insert(q, c)
                routes.pop(i)
            else:
                routes[j].insert(q, c)
                if len(routes[i]) == 0:
                    routes.pop(i)
            improved = True

    # ---------- cleanup: remove empty routes, final validation/order ----------
    routes = [r for r in routes if r]

    # Final guarantee: each customer exactly once by repairing any anomalies
    cnt = {}
    for r in routes:
        for c in r:
            cnt[c] = cnt.get(c, 0) + 1
    final_missing = [i for i in ids if cnt.get(i, 0) == 0]
    if final_missing:
        # append missing to feasible routes or create new singleton routes
        for c in final_missing:
            placed = False
            for r in routes:
                if load_of(r) + demand[c] <= cap:
                    r.append(c)
                    placed = True
                    break
            if not placed:
                routes.append([c])

    # Remove any duplicates if they survived
    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c in seen:
                continue
            if load + demand[c] <= cap:
                nr.append(c)
                seen.add(c)
                load += demand[c]
        if nr:
            cleaned.append(nr)
    routes = cleaned

    # Ensure all customers present; if not, add them as singleton routes
    present = set()
    for r in routes:
        for c in r:
            present.add(c)
    for c in ids:
        if c not in present:
            routes.append([c])

    return routes
